props:
className="flex-1 border-border-muted"
				size="md"
				items={storeItems}
				value={selectedStore}
				onValueChange={handleStoreChange}
				placeholder="Semua Toko"
				label="Pilih Toko"
				leftIcon={<StoreIcon size={tw(3.5)} color={Colors.zinc[400]} />}

className="flex-1 border-border-muted"
				size="md"
				items={periodItems}
				value={selectedPeriod}
				onValueChange={handlePeriodChange}
				placeholder="Hari Ini"
				label="Pilih Periode"
				leftIcon={<CalendarIcon size={tw(4)} color={Colors.zinc[400]} />}

label="Filter Sumber Dana"
								items={[
									{ label: "Semua sumber dana", value: "" },
									...EXPENSE_FUNDING_SOURCES,
								]}
								value={funding}
								onValueChange={setFunding}

label="Filter Toko"
								items={[{ label: "Semua toko", value: "" }, ...EXPENSE_STORES]}
								value={store}
								onValueChange={setStore}

label="Filter Pemasok"
							value={filter}
							onValueChange={setFilter}
							items={[
								{ label: "Semua Pemasok", value: "all" },
								{ label: "Supplier Aktif", value: "active" },
								{ label: "Supplier Utama", value: "primary" },
							]}

searchable
												label={input.label}
												placeholder={input.placeholder}
												value={field.value}
												items={regionOptions(input.name)}
												disabled={
													(input.name === "city" && !province) ||
													(input.name === "district" && !city)
												}
												onValueChange={(value) => {
													if (value === field.value) return;
													field.onChange(value);
													if (input.name === "province")
														form.setValue("city", "", { shouldValidate: true });
													if (input.name !== "district")
														form.setValue("district", "", {
															shouldValidate: true,
														});
												}}

items={MULTIPLE_OPTIONS}
									value={multiple}
									onValueChange={(value) =>
										setDraft((previous) => ({ ...previous, multiple: value }))
									}
									placeholder="Pilih Kelipatan Pembulatan"
									label="Kelipatan Pembulatan"
									variant="rounded"

items={[
								{ label: "Semua Toko", value: "all" },
								...INVENTORY_STORES.map((name) => ({
									label: name,
									value: name,
								})),
							]}
							value={store}
							onValueChange={setStore}
							label="Filter Toko"

items={STOCK_KIND_OPTIONS}
											value={field.value}
											onValueChange={(value) => {
												field.onChange(value);
												replace([]);
												form.clearErrors("lines");
											}}

items={availableItems.map((item) => ({
										label: item.name,
										value: item.id,
									}))}
									placeholder={`${isTransfer ? "Tambah" : "Pilih"} ${kind === "product" ? "Produk" : "Bahan Baku"}`}
									label="Pilih Stok"
									searchable
									variant="ghost"
									leftIcon={<InventoryIcon name="plus" />}
									onValueChange={(id) => {
										const item = getInventoryItem(id);
										append({ itemId: item.id, stock: item.stock, quantity: 0 });
										form.clearErrors("lines");
									}}

items={storeOptions}
						value={outlet}
						onValueChange={setOutlet}
						placeholder="Pilih toko untuk ditambahkan"
						label="Outlet / Toko"
						variant="rounded"

items={FREQUENCY_OPTIONS}
							value={frequency}
							onValueChange={setFrequency}
							placeholder="Pilih frekuensi"
							label="Frekuensi"
							variant="rounded"

items={[
								{ label: "Semua Toko", value: "all" },
								...INVENTORY_STORES.map((name) => ({
									label: name,
									value: name,
								})),
							]}
							value={store}
							onValueChange={setStore}
							label="Filter Toko"

items={STOCK_KIND_OPTIONS}
											value={field.value}
											onValueChange={(value) => {
												field.onChange(value);
												replace([]);
												form.clearErrors("lines");
											}}

variant="ghost"
									searchable
									placeholder={`Tambah ${kind === "product" ? "Produk" : "Bahan Baku"}`}
									label="Pilih Item Pembelian"
									leftIcon={<InventoryIcon name="plus" />}
									items={availableItems.map((item) => ({
										label: item.name,
										value: item.id,
									}))}
									onValueChange={(id) => {
										append({ itemId: id, quantity: 0, price: 0 });
										form.clearErrors("lines");
									}}

items={paymentMethodItems}
													value={field.value}
													onValueChange={(val) => {
														const currentName = form.getValues("name");
														const prevDefault = namePlaceholder;
														field.onChange(val);
														if (!currentName || currentName === prevDefault) {
															let newDefault = "Tunai";
															if (val === PaymentMethodType.QRIS) newDefault = "QRIS";
															else if (val === PaymentMethodType.BANK_TRANSFER) newDefault = "Transfer Bank";
															else if (val === PaymentMethodType.CREDIT_CARD) newDefault = "Kartu Kredit";
															else if (val === PaymentMethodType.DEBIT_CARD) newDefault = "Kartu Debit";
															else if (val === PaymentMethodType.OTHER) newDefault = "Lainnya";
															form.setValue("name", newDefault);
														}
													}}
													placeholder="Pilih jenis pembayaran"
													label="Jenis Pembayaran"

items={bankItems}
															value={field.value}
															onValueChange={field.onChange}
															placeholder="Pilih bank"
															label="Pilih Bank"
															searchable={true}

label="Filter Sumber Dana"
								items={[
									{ label: "Semua sumber dana", value: "" },
									...INCOME_FUNDING_SOURCES,
								]}
								value={funding}
								onValueChange={setFunding}

label="Filter Toko"
								items={[{ label: "Semua toko", value: "" }, ...INCOME_STORES]}
								value={store}
								onValueChange={setStore}

label="Filter Jenis Penerimaan"
						items={[
							{ label: "Semua penerimaan", value: "" },
							{ label: "Manual", value: "manual" },
							{ label: "Penjualan", value: "invoice" },
						]}
						value={type}
						onValueChange={setType}

className="bg-white"
										items={
											storesQuery.data?.map((store) => ({
												label: store.name,
												value: store.id,
											})) ?? [{ label: "Outlet Utama", value: "default-store" }]
										}
										value={form.watch("store_id") || ""}
										onValueChange={(val) => form.setValue("store_id", val)}
										placeholder="Pilih toko untuk ditambahkan"
										label="Pilih Toko"

className="bg-white"
											items={
												categoriesQuery.data?.map((cat) => ({
													label: cat.name,
													value: cat.id,
												})) ?? [{ label: "Makanan", value: "default-cat" }]
											}
											value={form.watch("category_id") || ""}
											onValueChange={(val) => form.setValue("category_id", val)}
											placeholder="Pilih Kategori"
											label="Pilih Kategori"

className="bg-white"
											items={
												brandsQuery.data?.map((b) => ({
													label: b.name,
													value: b.id,
												})) ?? [{ label: "Pizza Hut", value: "default-brand" }]
											}
											value={form.watch("brand_id") || ""}
											onValueChange={(val) => form.setValue("brand_id", val)}
											placeholder="Pilih Merk"
											label="Pilih Merk"

className="bg-white"
											items={
												unitsQuery.data?.map((u) => ({
													label: u.name,
													value: u.id,
												})) ?? [
													{ label: "Pcs", value: "pcs" },
													{ label: "Porsi", value: "porsi" },
												]
											}
											value={form.watch("unit_id") || ""}
											onValueChange={(val) => form.setValue("unit_id", val)}
											placeholder="Pilih Satuan"
											label="Pilih Satuan"

items={data}
			value={selectedItem?.value ?? formValue}
			onValueChange={(value) =>
				form.setValue(name, value, {
					shouldValidate: true,
					shouldDirty: true,
				})
			}
			placeholder={placeholder}
			label={label ?? placeholder}
			searchable={searchable}
			searchPlaceholder={searchPlaceholder}
			leftIcon={leftIcon}
			renderItemIcon={renderItemIcon}
			disabled={disabled}
			size={size}
			variant={variant}
			className={className}
			showConfirmButton={showConfirmButton}
			confirmText={confirmText}
			dismissOnSelect={dismissOnSelect}

isOpen={isSortOpen}
					onClose={() => setIsSortOpen(false)}
					value={sortBy}
					onChange={onSortChange}

items={availableMenus.map((m) => ({
																		label: m.name,
																		value: m.id,
																	}))}
																	value={field.value}
																	onValueChange={(val) => {
																		field.onChange(val);
																		const menuObj = availableMenus.find(
																			(m) => m.id === val,
																		);
																		if (menuObj?.variants?.[0]) {
																			form.setValue(
																				`details.${index}.variant_name`,
																				menuObj.variants[0],
																			);
																		}
																	}}
																	placeholder="Pilih item menu"
																	label="Pilih Menu"
																	variant="outline"

items={variantOptions}
																			value={field.value}
																			onValueChange={field.onChange}
																			placeholder="Pilih varian"
																			label="Pilih Varian"
																			variant="outline"

size="xl"
														variant="outline"
														items={SIZE_OPTIONS}
														value={field.value}
														onValueChange={field.onChange}

items={places.map((place) => ({
							value: place.id,
							label: place.name,
						}))}
						value={selectedId}
						onValueChange={setSelected}
						label="Pilih tempat untuk dipindahkan"

label="Periode Gaji"
							value={period}
							onValueChange={setPeriod}
							items={periods.map((value) => ({
								value,
								label: payrollPeriodLabel(value),
							}))}
							placeholder="Pilih periode"

label="Status Pembayaran"
							value={status}
							onValueChange={setStatus}
							items={[...PAYROLL_STATUSES]}
